## C. Key Structures, Macros, Function Signatures and Pseudocode

### C.1 Resource Table Initialization (pseudocode)

```c
/* In rv1126b_rptun.c, file scope */
static struct rptun_rsc_s g_rptun_rsc;
static bool g_rptun_rsc_ready;

static void rv1126b_rptun_rsc_init(void)
{
  struct rptun_rsc_s *rsc = &g_rptun_rsc;

  if (g_rptun_rsc_ready)
    return;

  memset(rsc, 0, sizeof(*rsc));

  /* Resource table header */
  rsc->rsc_tbl_hdr.ver         = 1;
  rsc->rsc_tbl_hdr.num         = 2;
  rsc->rsc_tbl_hdr.reserved[0] = 0;
  rsc->rsc_tbl_hdr.reserved[1] = 0;

  /* Offsets for find_rsc() */
  rsc->offset[0] = offsetof(struct rptun_rsc_s, rpmsg_vdev);
  rsc->offset[1] = offsetof(struct rptun_rsc_s, carveout);

  /* Virtio device */
  rsc->rpmsg_vdev.type          = RSC_VDEV;
  rsc->rpmsg_vdev.id            = VIRTIO_ID_RPMSG;
  rsc->rpmsg_vdev.dfeatures     = (1u << VIRTIO_RPMSG_F_NS)
                                | (1u << VIRTIO_RPMSG_F_ACK)
                                | (1u << VIRTIO_RPMSG_F_BUFSZ);
  rsc->rpmsg_vdev.config_len    = sizeof(struct fw_rsc_config);
  rsc->rpmsg_vdev.num_of_vrings = 2;
  rsc->rpmsg_vdev.status        = VIRTIO_CONFIG_STATUS_DRIVER_OK; /* PRE-SET */

  /* Vring 0 */
  rsc->rpmsg_vring0.da       = 0x48c3c000u;
  rsc->rpmsg_vring0.align    = 0x1000u;
  rsc->rpmsg_vring0.num      = 64u;
  rsc->rpmsg_vring0.notifyid = 0u;

  /* Vring 1 */
  rsc->rpmsg_vring1.da       = 0x48c44000u;
  rsc->rpmsg_vring1.align    = 0x1000u;
  rsc->rpmsg_vring1.num      = 64u;
  rsc->rpmsg_vring1.notifyid = 1u;

  /* Config */
  rsc->config.r2h_buf_size = 512u;
  rsc->config.h2r_buf_size = 512u;

  /* Carveout (DMA pool) */
  rsc->carveout.type = RSC_CARVEOUT;
  rsc->carveout.da   = 0x48c4c000u;
  rsc->carveout.pa   = FW_RSC_U32_ADDR_ANY;
  rsc->carveout.len  = 0x10000u;
  memcpy(rsc->carveout.name, "rpmsg_shm", 10);

  g_rptun_rsc_ready = true;
}

static struct resource_table *rp_get_resource(struct rptun_dev_s *dev)
{
  rv1126b_rptun_rsc_init();
  return &g_rptun_rsc.rsc_tbl_hdr;
  /* No shmem->base polling. Returns immediately. */
}
```

