### C.3 Mailbox ISR (pseudocode)

```c
static int rv1126b_mbox_isr(int irq, void *context, void *arg)
{
  uint32_t cmd, data, status;
  uintptr_t base = MBOX_RX_BASE;

  /* Read CMD then DATA with barriers between */
  cmd = getreg32(base + RV1126B_MBOX_A2B_CMD_OFFSET);
  UP_RMB();
  data = getreg32(base + RV1126B_MBOX_A2B_DATA_OFFSET);
  UP_RMB();
  status = getreg32(base + RV1126B_MBOX_A2B_STATUS_OFFSET);
  UP_RMB();

  /* Validate magic */
  if (data != 0x524d5347u)
    {
      /* Still clear status to avoid IRQ storm */
      putreg32(status, base + RV1126B_MBOX_A2B_STATUS_OFFSET);
      return OK;
    }

  /* W1C clear status */
  putreg32(status, base + RV1126B_MBOX_A2B_STATUS_OFFSET);
  UP_WMB();

  /* Call registered callback */
  if (g_mbox_callback != NULL)
    {
      g_mbox_callback(g_mbox_arg);
    }

  return OK;
}
```

### C.4 Mailbox Notify (pseudocode)

```c
int rv1126b_mailbox_notify(uint32_t vqid)
{
  uintptr_t base;
  uint32_t status_off;
  uint32_t cmd_off;
  uint32_t data_off;

  if (vqid == 0)
    {
      base       = MBOX_TX_VQ0_BASE;  /* MBOX4 */
      status_off = RV1126B_MBOX_B2A_STATUS_OFFSET;
      cmd_off    = RV1126B_MBOX_B2A_CMD_OFFSET;
      data_off   = RV1126B_MBOX_B2A_DATA_OFFSET;
    }
  else /* vqid == 1 */
    {
      base       = MBOX_TX_VQ1_BASE;  /* MBOX7 */
      status_off = RV1126B_MBOX_B2A_STATUS_OFFSET;
      cmd_off    = RV1126B_MBOX_B2A_CMD_OFFSET;
      data_off   = RV1126B_MBOX_B2A_DATA_OFFSET;
    }

  /* V2.0 busy check: spin-wait if B2A STATUS indicates previous TX unconsumed */
  int timeout = 100;
  while (timeout-- > 0 && getreg32(base + status_off) != 0)
    {
      /* brief spin, no sleep in potentially IRQ-off context */
      __asm__ volatile ("nop");
    }

  /* Write CMD, barrier, write DATA */
  putreg32(0x03u, base + cmd_off);       /* CMD = link-id */
  UP_WMB();
  putreg32(0x524d5347u, base + data_off); /* DATA = magic */

  return 0;
}
```

### C.5 Init/Deinit lifecycle

```c
int rv1126b_rptun_init(const char *peername)
{
  struct rv1126b_rptun_dev_s *dev = &g_rptun_dev;
  int ret;

  memset(dev, 0, sizeof(*dev));
  dev->master = false;

  /* 1. Initialize static resource table BEFORE framework needs it */
  rv1126b_rptun_rsc_init();

  /* 2. Initialize mailbox hardware */
  ret = rv1126b_mailbox_init(rv1126b_rptun_mbox_cb, dev);
  if (ret < 0)
    {
      rperr("mailbox_init failed: %d\n", ret);
      return ret;
    }

  /* 3. Configure and register RPTun device */
  dev->rptun.ops = &g_rv1126b_rptun_ops;
  strncpy(dev->peername, peername, RPMSG_NAME_SIZE);

  ret = rptun_initialize(&dev->rptun);
  if (ret < 0)
    {
      rperr("rptun_initialize failed: %d\n", ret);
      rv1126b_mailbox_deinit();
      return ret;
    }

  return OK;
}

int rv1126b_mailbox_init(rv1126b_mbox_callback_t callback, void *arg)
{
  int ret;

  g_mbox_callback = callback;
  g_mbox_arg      = arg;

  /* Clear all relevant STATUS registers (W1C) */
  putreg32(0xffffffffu, MBOX_RX_BASE + RV1126B_MBOX_A2B_STATUS_OFFSET);
  putreg32(0xffffffffu, MBOX_RX_BASE + RV1126B_MBOX_B2A_STATUS_OFFSET);
  putreg32(0xffffffffu, MBOX_TX_VQ0_BASE + RV1126B_MBOX_B2A_STATUS_OFFSET);

  /* RX: MBOX7 A2B, enable TX_DONE + TRIG_MODE */
  putreg32(RV1126B_MBOX_INT_TX_DONE | RV1126B_MBOX_INT_TRIG_MODE,
           MBOX_RX_BASE + RV1126B_MBOX_A2B_INTEN_OFFSET);

  /* TX vqid0: MBOX4 B2A, TRIG_MODE only */
  putreg32(RV1126B_MBOX_INT_TRIG_MODE,
           MBOX_TX_VQ0_BASE + RV1126B_MBOX_B2A_INTEN_OFFSET);

  /* TX vqid1: MBOX7 B2A, TRIG_MODE only */
  putreg32(RV1126B_MBOX_INT_TRIG_MODE,
           MBOX_TX_VQ1_BASE + RV1126B_MBOX_B2A_INTEN_OFFSET);

  /* Attach IRQ */
  ret = irq_attach(MBOX_RX_IRQ, rv1126b_mbox_isr, NULL);
  if (ret < 0)
    {
      return ret;
    }
  up_enable_irq(MBOX_RX_IRQ);

  return OK;
}
```

